$filters=['start_date'=>trim($_GET['start_date']??''),'end_date'=>trim($_GET['end_date']??''),'academic_year_id'=>(int)($_GET['academic_year_id']??0),'nivel_educativo'=>trim($_GET['nivel_educativo']??''),'grado'=>trim($_GET['grado']??''),'seccion'=>trim($_GET['seccion']??''),'student_id'=>(int)($_GET['student_id']??0),'payment_method_id'=>(int)($_GET['payment_method_id']??0),'course_id'=>(int)($_GET['course_id']??0),'student_status'=>trim($_GET['student_status']??''),'operation_status'=>trim($_GET['operation_status']??'Confirmado')];
$years=[];$activeYear=0;$stmt=$conn->prepare('SELECT id,year,is_active FROM academic_year WHERE school_id=? ORDER BY year DESC');$stmt->bind_param('i',$schoolId);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$years[]=$row;if((int)$row['is_active']===1)$activeYear=(int)$row['id'];}$stmt->close();if($filters['academic_year_id']===0)$filters['academic_year_id']=$activeYear;
$students=[];$stmt=$conn->prepare('SELECT id,id_no,name FROM student WHERE school_id=? ORDER BY name');$stmt->bind_param('i',$schoolId);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc())$students[]=$row;$stmt->close();
$methods=[];$result=$conn->query('SELECT id,name FROM payment_methods ORDER BY name');while($result&&($row=$result->fetch_assoc()))$methods[]=$row;
$courses=[];$stmt=$conn->prepare('SELECT c.id,c.course,c.level,ay.year FROM courses c LEFT JOIN academic_year ay ON ay.id=c.academic_year_id WHERE ay.school_id=? ORDER BY ay.year DESC,c.course');$stmt->bind_param('i',$schoolId);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc())$courses[]=$row;$stmt->close();
?>
