tatus"><option value="">Todos</option><?php foreach(['Activo','Retirado','Egresado'] as $item): ?><option <?php echo $filters['student_status']===$item?'selected':''; ?>><?php echo $item; ?></option><?php endforeach; ?></select></div><div><label>Estudiante</label><select class="form-control form-control-sm pr-select2" name="student_id"><option value="">Todos</option><?php foreach($students as $item): ?><option value="<?php echo (int)$item['id']; ?>" <?php echo $filters['student_id']===(int)$item['id']?'selected':''; ?>><?php echo htmlspecialchars($item['id_no'].' - '.$item['name']); ?></option><?php endforeach; ?></select></div><div><label>Concepto</label><select class="form-control form-control-sm pr-select2" name="course_id"><option value="">Todos</option><?php foreach($courses as $item): ?><option value="<?php echo (int)$item['id']; ?>" <?php echo $filters['course_id']===(int)$item['id']?'selected':''; ?>><?php echo htmlspecialchars($item['course'].' · '.$item['level'].' · '.($item['year']??'Sin año')); ?></option><?php endforeach; ?></select></div><div><label>Medio de pago</label><select class="form-control form-control-sm" name="payment_method_id"><option value="">Todos</option><?php foreach($methods as $item): ?><option value="<?php echo (int)$item['id']; ?>" <?php echo $filters['payment_method_id']===(int)$item['id']?'selected':''; ?>><?php echo htmlspecialchars($item['name']); ?></option><?php endforeach; ?></select></div><div class="d-flex align-items-end"><button class="btn btn-primary btn-sm mr-2"><i class="fas fa-filter mr-1"></i>Aplicar</button><a class="btn btn-light border btn-sm" href="index.php?page=payments_report">Limpiar</a></div></div></form>
