<script>
function openPaymentsPrintPreview(url){var frame=$('#payments-print-frame'),loading=$('#payments-print-loading');frame.hide().attr('src','about:blank');loading.removeClass('d-none').addClass('d-flex');$('#payments-print-modal').modal('show');frame.off('load.paymentsPrint').on('load.paymentsPrint',function(){if(this.src==='about:blank')return;loading.removeClass('d-flex').addClass('d-none');frame.show()}).attr('src',url)}
$('#payments-print-modal').on('hidden.bs.modal',function(){$('#payments-print-frame').attr('src','about:blank').hide();$('#payments-print-loading').removeClass('d-none').addClass('d-flex')});
$(function(){const gradeMap={Inicial:['3 años','4 años','5 años'],Primaria:['1°','2°','3°','4°','5°','6°'],Secundaria:['1°','2°','3°','4°','5°']},selectedGrade=<?php echo json_encode($filters['grado'],JSON_UNESCAPED_UNICODE); ?>,$level=$('[name="nivel_educativo"]'),old=$('[name="grado"]'),grade=$('<select class="form-control form-control-sm" name="grado"></select>');old.replaceWith(grade);function loadPaymentGrades(value){let level=$level.val(),items=gradeMap[level]||[];grade.empty();if(!level){grade.append(new Option('Seleccione un nivel','')).prop('disabled',true);return}grade.append(new Option('Todos',''));items.forEach(item=>grade.append(new Option(item,item)));grade.prop('disabled',false);if(value&&items.indexOf(value)>=0)grade.val(value)}$level.on('change',function(){loadPaymentGrades('')});loadPaymentGrades(selectedGrade)});
$(function(){
 if($.fn.select2)$('.pr-select2').select2({width:'100%'});if(!$.fn.DataTable||!$('#payments-report-table').length)return;
 const reportFilters=<?php echo json_encode($filters,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;let table=null,view='detail';
 const money=v=>'S/ '+Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});const esc=v=>$('<div>').text(v==null?'':v).html();const date=v=>{if(!v)return'—';let p=String(v).substring(0,10).split('-');return p.length===3?p[2]+'/'+p[1]+'/'+p[0]:v};
 const configs={
  detail:{heads:['Fecha','Recibo','Estudiante','Conceptos cubiertos','Medios','Descuento','Total','Estado','Acción'],cols:Array.from({length:9},(_,i)=>({data:i,orderable:![3,4,5,8].includes(i)}))},
  student:{heads:['Estudiante','Aula','Operaciones','Confirmadas','Anuladas','Descuentos','Total confirmado','Total anulado','Último pago'],cols:[{data:null,render:r=>'<strong>'+esc(r.student_name)+'</strong><div class="small text-muted">'+esc(r.id_no)+'</div>'},{data:null,render:r=>esc(r.nivel+' · '+r.grado+' '+r.seccion)},{data:'operations'},{data:'confirmed_operations'},{data:'cancelled_operations'},{data:'discount_amount',render:money},{data:'confirmed_amount',render:money},{data:'cancelled_amount',render:money},{data:'last_payment',render:date}]},
  concept:{heads:['Concepto','Año','Operaciones','Estudiantes','Total confirmado','Total anulado'],cols:[{data:'concept_name',render:v=>'<strong>'+esc(v)+'</strong>'},{data:'academic_year',defaultContent:'—'},{data:'operations'},{data:'students'},{data:'confirmed_amount',render:money},{data:'cancelled_amount',render:money}]},
  method:{heads:['Medio de pago','Operaciones','Estudiantes','Total confirmado','Total anulado'],cols:[{data:'method_name',render:v=>'<strong>'+esc(v)+'</strong>'},{data:'operations'},{data:'students'},{data:'confirmed_amount',render:money},{data:'cancelled_amount',render:money}]},
  daily:{heads:['Fecha','Operaciones','Confirmadas','Anuladas','Estudiantes','Descuentos','Total confirmado','Total anulado'],cols:[{data:'payment_day',render:date},{data:'operations'},{data:'confirmed_operations'},{data:'cancelled_operations'},{data:'students'},{data:'discount_amount',render:money},{data:'confirmed_amount',render:money},{data:'cancelled_amount',render:money}]}
 };
 function updateSummary(json){let s=json.summary||{};$('#pr-count').text(Number(s.count||0).toLocaleString('es-PE'));$('#pr-confirmed').text(money(s.confirmed));$('#pr-cancelled').text(money(s.cancelled));$('#pr-discounts').text(money(s.discounts))}
 function init(){let c=configs[view];if(table){table.destroy();$('#payments-report-table').empty()}$('#payments-report-table').append('<thead><tr>'+c.heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody></tbody>');table=$('#payments-report-table').DataTable({serverSide:true,processing:true,pageLength:25,lengthMenu:[[25,50,100],[25,50,100]],order:[],ajax:{url:'payments_report_data.php',type:'GET',data:d=>$.extend(d,reportFilters,{view:view}),dataSrc:function(json){$('#pr-error').addClass('d-none').empty();updateSummary(json);return json.data||[]},error:function(xhr){let message='No se pudo cargar el reporte de pagos.';try{let response=JSON.parse(xhr.responseText);message=response.error||response.message||message}catch(e){}$('#pr-error').removeClass('d-none').text(message)}},columns:c.cols,language:{search:'Buscar:',lengthMenu:'Mostrar _MENU_',processing:'Cargando pagos...',zeroRecords:'No se encontraron pagos',info:'Mostrando _START_ a _END_ de _TOTAL_',infoEmpty:'Sin operaciones',paginate:{previous:'Anterior',next:'Siguiente'}}})}
 const viewHelp={detail:'Cada fila representa una operación de pago.',student:'Totales acumulados por estudiante.',concept:'Recaudación agrupada por concepto de pago.',method:'Importes agrupados por medio de pago.',daily:'Resumen de operaciones por fecha.'};
 $('.pr-tabs button').on('click',function(){view=$(this).data('view');$('.pr-tabs button').removeClass('btn-primary').addClass('btn-outline-primary');$(this).addClass('btn-primary').removeClass('btn-outline-primary');$('#pr-view-help').text(viewHelp[view]||'');init()});init();
});
</script>
